    typealias SwiftType = Machine

    public static func lift(_ handle: UInt64) throws -> Machine {
        return Machine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Machine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Machine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

