/**
 * The part of a workspace this frontend lets the user edit
 */
public struct MachineConfig: Equatable, Hashable {
    public var romPath: String
    /**
     * Model index, or None to detect the model from the ROM
     */
    public var model: UInt32?
    /**
     * Display card ROM (Macintosh II family) or video ROM (SE/30)
     */
    public var displayRomPath: String?
    public var displayCard: DisplayCard
    /**
     * What's attached at each SCSI ID (0-6)
     */
    public var scsiDevices: [ScsiDevice]
    /**
     * How an Ethernet controller connects, if there is one
     */
    public var ethernetLink: EthernetLink
    /**
     * File to keep the PRAM in, or None to not persist it
     */
    public var pramPath: String?
    public var audio: Bool
    /**
     * RAM size in bytes, or None for the model's default
     */
    public var ramSize: UInt64?
    /**
     * Video RAM size in bytes, or None for the model's default
     */
    public var vramSize: UInt64?
    /**
     * FPU fitted (LC family), or the CPU is a full 68040 (LC 475)
     */
    public var fpu: Bool
    /**
     * 68851 PMMU fitted (Macintosh II)
     */
    public var pmmu: Bool
    /**
     * The floppy drive is the 800K one (Macintosh 128K and 512K)
     */
    public var floppy800k: Bool
    /**
     * The monitor connected, or None for the default
     */
    public var monitor: Monitor?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(romPath: String, 
        /**
         * Model index, or None to detect the model from the ROM
         */model: UInt32?, 
        /**
         * Display card ROM (Macintosh II family) or video ROM (SE/30)
         */displayRomPath: String?, displayCard: DisplayCard, 
        /**
         * What's attached at each SCSI ID (0-6)
         */scsiDevices: [ScsiDevice], 
        /**
         * How an Ethernet controller connects, if there is one
         */ethernetLink: EthernetLink, 
        /**
         * File to keep the PRAM in, or None to not persist it
         */pramPath: String?, audio: Bool, 
        /**
         * RAM size in bytes, or None for the model's default
         */ramSize: UInt64?, 
        /**
         * Video RAM size in bytes, or None for the model's default
         */vramSize: UInt64?, 
        /**
         * FPU fitted (LC family), or the CPU is a full 68040 (LC 475)
         */fpu: Bool, 
        /**
         * 68851 PMMU fitted (Macintosh II)
         */pmmu: Bool, 
        /**
         * The floppy drive is the 800K one (Macintosh 128K and 512K)
         */floppy800k: Bool, 
        /**
         * The monitor connected, or None for the default
         */monitor: Monitor?) {
        self.romPath = romPath
        self.model = model
        self.displayRomPath = displayRomPath
        self.displayCard = displayCard
        self.scsiDevices = scsiDevices
        self.ethernetLink = ethernetLink
        self.pramPath = pramPath
        self.audio = audio
        self.ramSize = ramSize
        self.vramSize = vramSize
        self.fpu = fpu
        self.pmmu = pmmu
        self.floppy800k = floppy800k
        self.monitor = monitor
    }

    

    
}

