     * A folder, whose files are made into a disc when it's inserted
     */
    case folder(path: String
    )





}

#if compiler(>=6)
extension CdromDisc: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCdromDisc: FfiConverterRustBuffer {
    typealias SwiftType = CdromDisc

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CdromDisc {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .image(path: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .folder(path: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CdromDisc, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .image(path):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .folder(path):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(path, into: &buf)
            
        }
    }
}


